import{_ as i,a0 as p,w as a,s as m,ao as n,I as o,x as e,a1 as l,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux有问必答：如何通过命令行创建和设置一个MySQL用户 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何通过命令行创建和设置一个MySQL用户 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何通过命令行创建和设置一个MySQL用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何通过命令行创建和设置一个MySQL用户 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150122 Linux FAQs with Answers--How to create and configure a MySQL user from the command line","title":"Linux有问必答：如何通过命令行创建和设置一个MySQL用户","tag":"201503","desc":""},"relativePath":"201503/20150122 Linux FAQs with Answers--How to create and configure a MySQL user from the command line.md","filePath":"[post].md"}'),u={name:"201503/20150122 Linux FAQs with Answers--How to create and configure a MySQL user from the command line.md"};function d(g,t,y,S,L,T){const r=p("Link");return a(),m("div",null,[t[19]||(t[19]=n(`<h1 id="linux有问必答-如何通过命令行创建和设置一个mysql用户" tabindex="-1">Linux有问必答：如何通过命令行创建和设置一个MySQL用户 <a class="header-anchor" href="#linux有问必答-如何通过命令行创建和设置一个mysql用户" aria-label="Permalink to “Linux有问必答：如何通过命令行创建和设置一个MySQL用户”">​</a></h1><blockquote><p><strong>问题</strong>：我想要在MySQL服务器上创建一个新的用户帐号，并且赋予他适当的权限和资源限制。如何通过命令行的方式来创建并且设置一个MySQL用户呢？</p></blockquote><p>要访问一个MySQL服务器，你需要使用一个用户帐号登录其中方可进行。每个MySQL用户帐号都有许多与之相关连的属性，例如用户名、密码以及权限和资源限制。&quot;权限&quot;定义了特定用户能够在MySQL服务器中做什么，而&quot;资源限制&quot;为用户设置了一系列服务器资源的使用许可。创建或更新一个用户涉及到了对用户帐号所有属性的管理。</p><p>下面展示了如何在Linux中创建和设置一个MySQL用户。</p><p>首先以root身份登录到MySQL服务器中。</p><pre><code>$ mysql -u root -p
</code></pre><p>当验证提示出现的时候，输入MySQL的root帐号的密码。</p><p><img src="https://farm8.staticflickr.com/7482/16024190060_fff53d8840_b.jpg" alt=""></p><h3 id="创建一个mysql用户" tabindex="-1">创建一个MySQL用户 <a class="header-anchor" href="#创建一个mysql用户" aria-label="Permalink to “创建一个MySQL用户”">​</a></h3><p>使用如下命令创建一个用户名和密码分别为&quot;myuser&quot;和&quot;mypassword&quot;的用户。</p><pre><code>mysql&gt; CREATE USER &#39;myuser&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;mypassword&#39;;
</code></pre><p>一旦用户被创建后，包括加密的密码、权限和资源限制在内的所有帐号细节都会被存储在一个名为<strong>user</strong>的表中，这个表则存在于<strong>mysql</strong>这个特殊的数据库里。</p><p>运行下列命令，验证帐号是否创建成功</p><pre><code>mysql&gt; SELECT host, user, password FROM mysql.user WHERE user=&#39;myuser&#39;;
</code></pre><h3 id="赋予mysql用户权限" tabindex="-1">赋予MySQL用户权限 <a class="header-anchor" href="#赋予mysql用户权限" aria-label="Permalink to “赋予MySQL用户权限”">​</a></h3><p>一个新建的MySQL用户没有任何访问权限，这就意味着你不能在MySQL数据库中进行任何操作。你得赋予用户必要的权限。以下是一些可用的权限：</p><ul><li><strong>ALL</strong>: 所有可用的权限</li><li><strong>CREATE</strong>: 创建库、表和索引</li><li><strong>LOCK_TABLES</strong>: 锁定表</li><li><strong>ALTER</strong>: 修改表</li><li><strong>DELETE</strong>: 删除表</li><li><strong>INSERT</strong>: 插入表或列</li><li><strong>SELECT</strong>: 检索表或列的数据</li><li><strong>CREATE_VIEW</strong>: 创建视图</li><li><strong>SHOW_DATABASES</strong>: 列出数据库</li><li><strong>DROP</strong>: 删除库、表和视图</li></ul><p>运行以下命令赋予&quot;myuser&quot;用户特定权限。</p><pre><code>mysql&gt; GRANT &lt;privileges&gt; ON &lt;database&gt;.&lt;table&gt; TO &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p>以上命令中，<code>&lt;privileges&gt;</code> 代表着用逗号分隔的权限列表。如果你想要将权限赋予任意数据库（或表），那么使用星号（*）来代替数据库（或表）的名字。</p><p>例如，为所有数据库/表赋予 CREATE 和 INSERT 权限：</p><pre><code>mysql&gt; GRANT CREATE, INSERT ON *.* TO &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p>验证给用户赋予的全权限：</p><pre><code>mysql&gt; SHOW GRANTS FOR &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p><img src="https://farm8.staticflickr.com/7556/16209665261_923282bddd_c.jpg" alt=""></p><p>将全部的权限赋予所有数据库/表：</p><pre><code>mysql&gt; GRANT ALL ON *.* TO &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p>你也可以将用户现有的权限删除。使用以下命令废除&quot;myuser&quot;帐号的现有权限：</p><pre><code>mysql&gt; REVOKE &lt;privileges&gt; ON &lt;database&gt;.&lt;table&gt; FROM &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><h3 id="为用户添加资源限制" tabindex="-1">为用户添加资源限制 <a class="header-anchor" href="#为用户添加资源限制" aria-label="Permalink to “为用户添加资源限制”">​</a></h3><p>在MySQL中，你可以为单独的用户设置MySQL的资源使用限制。可用的资源限制如下：</p>`,31)),o("ul",null,[t[4]||(t[4]=o("li",null,[o("strong",null,"MAX_QUERIES_PER_HOUR"),e(": 允许的每小时最大请求数量")],-1)),t[5]||(t[5]=o("li",null,[o("strong",null,"MAX_UPDATES_PER_HOUR"),e(": 允许的每小时最大更新数量")],-1)),o("li",null,[t[1]||(t[1]=o("strong",null,"MAX_CONNECTIONS_PER_HOUR",-1)),t[2]||(t[2]=e(": 允许的每小时最大连接（译者注：",-1)),l(r,{href:"http://dev.mysql.com/doc/refman/5.0/en/user-resources.html"},{default:s(()=>[...t[0]||(t[0]=[e("其与 MySQL全局变量： max_user_connections 共同决定用户到数据库的同时连接数量",-1)])]),_:1}),t[3]||(t[3]=e("）数量",-1))]),t[6]||(t[6]=o("li",null,[o("strong",null,"MAX_USER_CONNECTIONS"),e(": 对服务器的同时连接量")],-1))]),t[20]||(t[20]=n(`<p>使用以下命令为&quot;myuser&quot;帐号增加一个资源限制：</p><pre><code>mysql&gt; GRANT USAGE ON &lt;database&gt;.&lt;table&gt; TO &#39;myuser&#39;@&#39;localhost&#39; WITH &lt;resource-limits&gt;;
</code></pre><p>在 <code>&lt;resource-limits&gt;</code> 中你可以指定多个使用空格分隔开的资源限制。</p><p>例如，增加 MAX_QUERIES_PER_HOUR 和 MAX_CONNECTIONS_PER_HOUR 资源限制：</p><pre><code>mysql&gt; GRANT USAGE ON *.* TO &#39;myuser&#39;@&#39;localhost&#39; WITH MAX_QUERIES_PER_HOUR 30 MAX_CONNECTIONS_PER_HOUR 6;
</code></pre><p>验证用户的资源限制：</p><pre><code>mysql&gt; SHOW GRANTS FOR &#39;myuser&#39;@&#39;localhost;
</code></pre><p><img src="https://farm8.staticflickr.com/7537/16025443759_5cb4177bc6_c.jpg" alt=""></p><p>创建和设置一个MySQL用户最后的一个重要步骤：</p><pre><code>mysql&gt; FLUSH PRIVILEGES;
</code></pre><p>如此一来更改便生效了。现在MySQL用户帐号就可以使用了。</p><hr>`,12)),o("p",null,[t[8]||(t[8]=e("via: ",-1)),l(r,{href:"http://ask.xmodulo.com/create-configure-mysql-user-command-line.html"},{default:s(()=>[...t[7]||(t[7]=[e("http://ask.xmodulo.com/create-configure-mysql-user-command-line.html",-1)])]),_:1})]),o("p",null,[t[11]||(t[11]=e("译者：",-1)),l(r,{href:"http://weibo.com/370321376"},{default:s(()=>[...t[9]||(t[9]=[e("Ping",-1)])]),_:1}),t[12]||(t[12]=o("br",null,null,-1)),t[13]||(t[13]=e(" 校对：",-1)),l(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创翻译，",-1)),l(r,{href:"http://linux.cn/"},{default:s(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const A=i(u,[["render",d]]);export{f as __pageData,A as default};
